'use strict';

const { runPy } = require('../helper');

function drawHeatmap(cameraId,
  {
    start,
    end = Date.now(),
    type = 'person',
    ...rest
  } = {},
  srcDir = './data'
) {
  const id = Array.isArray(cameraId)
    ? cameraId.join(',')
    : cameraId

  return runPy('draw_heatmap.py', {
    args: [
      '-id', id,
      '-heatmap', srcDir,
      '-s', start,
      '-e', end,
      '-type', type,
    ],
    ...rest,
  })
}

module.exports = drawHeatmap;
